import csv
import math


def run(inputs, output, params, context):
    with inputs[0].open("r", encoding="utf-8-sig", newline="") as source:
        reader = csv.DictReader(source)
        with output.open("w", encoding="utf-8", newline="") as target:
            writer = csv.DictWriter(target, fieldnames=reader.fieldnames, lineterminator="\n")
            writer.writeheader()
            for index, row in enumerate(reader, start=2):
                if None in row or any(value is None for value in row.values()):
                    raise ValueError(f"Row {index} has the wrong number of fields")
                try:
                    value = float(row["CD3"])
                except ValueError as exc:
                    raise ValueError(f"Invalid CD3 at row {index}") from exc
                if not math.isfinite(value):
                    raise ValueError(f"Nonfinite CD3 at row {index}")
                if value > params["threshold"]:
                    writer.writerow(row)
